            local f,err=io.open(path,'rb');if not f then return nil,err end
            local raw=f:read(8*1024*1024+1);f:close()
            if not raw or #raw>8*1024*1024 then return nil,'Файл слишком большой'end
            return raw
        end,
        run=function(fn)
            lua_thread.create(function()wait(0);fn()end)
        end,
        yield=function()wait(0)end,
        register=sampRegisterChatCommand,
        open=function()O3=F3.arbitrage;M3[0]=true end,
        find=function(number,server)
            if server~=PalatkaMCR.host.server()then
                PalatkaMCR.error='Сервер изменился';return
            end
            local n=PalatkaMCR.engine.integer(number,1,1000000000)
            if n then sampSendChat('/findilavka '..tostring(n))end
        end,
        read=function(name)
            local path=root..'/'..name
            if not Y.attributes(path)then return nil end
            local file,err=io.open(path,'rb')
            if not file then return nil,err end
            local content=file:read(8*1024*1024+1)
            file:close()
            if not content or #content>8*1024*1024 then return nil,'Файл слишком большой или не читается'end
            return content
        end,
        write=function(name,content)
            if not Y.attributes(root)then
                local ok,err=Y.mkdir(root)
                if not ok then return false,err end
            end
            local path=root..'/'..name
            local tmp=path..'.tmp'
            local file,err=io.open(tmp,'wb')
            if not file then return false,err end
            local ok,why=file:write(content)
            local closed,close_err=file:close()
            if not ok then return false,why end
            if not closed then return false,close_err end
            local renamed,rename_err=os.rename(tmp,path)
            if not renamed then return false,rename_err end
            return true
        end,
    })
end


(function(G)
-- Network policy for the standalone local client. Remote MCR features report
-- unavailable; this does not synthesize successful replies from its server.
do
    local reason='Не используется сервер MCR: доступна локальная работа'
    local allowed={['api.telegram.org']=true,['server-api.arizona.games']=true,
        ['server-api.azgames-cdn.ru']=true}
    local function permitted(url)
        local host=tostring(url or ''):match('^https://([^/:]+)')
        return host and allowed[host:lower()]==true
    end
    local old_http=lIl_l_lI
    lIl_l_lI=function(method,url,options,success,failure,timeout)
        if not permitted(url)then
            if failure then failure(reason)end
            return false,reason
        end
        return old_http(method,url,options,success,failure,timeout)
    end
    local old_chunks=lIl__IIl
    lIl__IIl=function(url,success,failure)
        if not permitted(url)then
            if failure then failure(reason)end
            return false,reason
        end
        return old_chunks(url,success,failure)
    end
    local old_request=G.request
    G.request=function(request,...)
        local url=type(request)=='table'and request.url or request
        if not permitted(url)then return nil,reason end
        return old_request(request,...)
    end
    PalatkaMCR.local_mode=true
end

end)(G)

